func TestLoadConfig(t *testing.T) {
	tests := []struct {
		name string
		in   string
		want time.Duration
	}{
		{"default timeout", `{}`, 30 * time.Second},
		{"explicit timeout", `{"timeout":"5s"}`, 5 * time.Second},
		{"zero means default", `{"timeout":"0s"}`, 30 * time.Second},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			cfg, err := LoadConfig([]byte(tt.in))
			requireNoError(t, err)
			if cfg.Timeout != tt.want {
				t.Errorf("LoadConfig(%s).Timeout = %v, want %v", tt.in, cfg.Timeout, tt.want)
			}
		})
	}
}

func requireNoError(t *testing.T, err error) {
	if err != nil {
		t.Errorf("unexpected error: %v", err)
	}
}
